# Compatible audio loader: use librosa first, then FFmpeg for formats such as
# M4A/AAC/FLAC/OGG/OPUS that may not be readable by the installed decoder.
def load_audio_compatible(path, sr=22050, mono=True, duration=None):
    try:
        return librosa.load(path, sr=sr, mono=mono, duration=duration)
    except Exception as librosa_error:
        ffmpeg = shutil.which("ffmpeg")
        if not ffmpeg:
            raise librosa_error
        cmd = [ffmpeg, "-nostdin", "-v", "error", "-i", str(path)]
        if duration is not None:
            cmd += ["-t", str(float(duration))]
        if mono:
            cmd += ["-ac", "1"]
        if sr:
            cmd += ["-ar", str(int(sr))]
        cmd += ["-f", "f32le", "-acodec", "pcm_f32le", "pipe:1"]
        decoded = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
        if decoded.returncode != 0 or not decoded.stdout:
            detail = decoded.stderr.decode("utf-8", errors="replace")[-240:]
            raise RuntimeError(f"librosa failed ({librosa_error}); FFmpeg could not decode this file: {detail}")
        audio = np.frombuffer(decoded.stdout, dtype=np.float32).copy()
        if not len(audio):
            raise RuntimeError("The audio file decoded to no samples.")
        return audio, int(sr or 22050)

