class _ManualAudioClassifier:
    """Drop-in replacement for transformers.pipeline("audio-classification").

    It only needs torch + AutoFeatureExtractor/AutoModelForAudioClassification, so the site keeps working even when
    `from transformers import pipeline` fails because of optional audio/vision integrations.
    Same call style as the pipeline: clf(dict_or_list_of_dicts, top_k=..., batch_size=...).
    """
    def __init__(self, model_id, device_index):
        from transformers import AutoFeatureExtractor, AutoModelForAudioClassification
        self.extractor = AutoFeatureExtractor.from_pretrained(model_id)
        self.model = AutoModelForAudioClassification.from_pretrained(model_id)
        self.device = torch.device("cuda" if device_index == 0 and torch.cuda.is_available() else "cpu")
        self.model.to(self.device).eval()
        self.id2label = dict(getattr(self.model.config, "id2label", {}) or {})
        self.sampling_rate = int(getattr(self.extractor, "sampling_rate", 16000) or 16000)

    def _label(self, index):
        return str(self.id2label.get(index, self.id2label.get(str(index), f"LABEL_{index}")))

    def _prepare(self, item):
        arr = np.asarray(item["raw"], dtype=np.float32).reshape(-1)
        sr = int(item.get("sampling_rate", self.sampling_rate))
        if sr != self.sampling_rate:
            arr = librosa.resample(arr, orig_sr=sr, target_sr=self.sampling_rate)
        return arr

    def _predict_batch(self, arrays, top_k):
        try:
            inputs = self.extractor(arrays, sampling_rate=self.sampling_rate, return_tensors="pt", padding=True)
        except TypeError:
            inputs = self.extractor(arrays, sampling_rate=self.sampling_rate, return_tensors="pt")
        inputs = {k: v.to(self.device) for k, v in inputs.items() if hasattr(v, "to")}
        with torch.inference_mode():
            logits = self.model(**inputs).logits
        probs = torch.softmax(logits.float(), dim=-1).cpu().numpy()
        k = max(1, min(int(top_k or 5), probs.shape[-1]))
        results = []
        for row in probs:
            order = np.argsort(-row)[:k]
            results.append([{"label": self._label(int(i)), "score": float(row[i])} for i in order])
        return results

    def __call__(self, inputs, top_k=5, batch_size=8, **_ignored):
        single = isinstance(inputs, dict)
        items = [inputs] if single else list(inputs)
        arrays = [self._prepare(item) for item in items]
        results = []
        step = max(1, int(batch_size or 1))
        for start in range(0, len(arrays), step):
            results.extend(self._predict_batch(arrays[start:start + step], top_k))
        return results[0] if single else results


def _build_classifier(model_id):
    """Try the standard transformers pipeline first; fall back to the built-in loader if it is unavailable."""
    if pipeline is not None:
        try:
            return pipeline("audio-classification", model=model_id, device=device)
        except Exception as exc:
            print(f"pipeline() failed for {model_id} ({exc.__class__.__name__}: {str(exc)[:120]}). Trying the built-in loader...")
    return _ManualAudioClassifier(model_id, device)


def _load_audio_model():
    global clf, MODEL_NAME, MODEL_STATUS, MODEL_ERROR
    errors = []
    for mid in MODEL_IDS:
        try:
            candidate = _build_classifier(mid)
            # Warm-up is intentionally omitted here; it can add a noticeable delay.
            with _MODEL_LOCK:
                clf = candidate
                MODEL_NAME = mid
                MODEL_STATUS = "Ready"
                MODEL_ERROR = ""
            print(f"Model ready: {MODEL_NAME} | Device: {'GPU' if device == 0 else 'CPU'}")
            return
        except Exception as exc:
            errors.append(f"{mid}: {exc.__class__.__name__}: {str(exc)[:180]}")
            print(f"Model load failed for {mid}: {exc}")
    with _MODEL_LOCK:
        MODEL_STATUS = "Unavailable"
        MODEL_ERROR = " | ".join(errors)
    print("WARNING: No audio-classification model could be loaded. The website is still available; audio prediction requires internet access and a successful model download.")

_model_thread = threading.Thread(target=_load_audio_model, name="GenreLensModelLoader", daemon=True)
