def voice_music_detector(path,verified):
    require_human(verified)
    if not path: raise gr.Error("Upload a clip first.")
    try:
        y,sr=load_audio_compatible(path,sr=22050,mono=True,duration=45)
        if len(y)<sr: raise gr.Error("Please upload at least one second of audio.")
        rms=float(np.mean(librosa.feature.rms(y=y))); zcr=float(np.mean(librosa.feature.zero_crossing_rate(y))); centroid=float(np.mean(librosa.feature.spectral_centroid(y=y,sr=sr))); flatness=float(np.mean(librosa.feature.spectral_flatness(y=y)))
        harmonic,percussive=librosa.effects.hpss(y); he=float(np.mean(harmonic**2)); pe=float(np.mean(percussive**2)); ratio=he/(pe+1e-9)
        if flatness>.16 and zcr>.12: label,conf,detail="Possibly speech / noisy audio",55,"High noise and zero-crossing rate can occur in speech, noise, or percussion."
        elif ratio>1.8 and centroid<3500: label,conf,detail="Possibly voice or melodic audio",58,"Harmonic energy is prominent; singing and instruments can share this pattern."
        elif pe>he*.8: label,conf,detail="Possibly instrumental / beat-heavy audio",56,"Percussive energy is prominent; voices may still be present."
        else: label,conf,detail="Mixed or uncertain audio",50,"The indicators do not clearly separate speech, singing, and instruments."
        html=f'<div class="result"><h2>🎙️ {label}</h2><p>Heuristic indicator: {conf}% (not calibrated model confidence)</p><div class="chips"><span class="chip">RMS {rms:.4f}</span><span class="chip">ZCR {zcr:.3f}</span><span class="chip">Centroid {centroid:.0f} Hz</span><span class="chip">Flatness {flatness:.3f}</span></div><p style="margin-top:14px">{detail}</p><small>Reliable detection requires a dedicated trained audio classifier.</small></div>'
        return html,pd.DataFrame([["Estimated category",label],["Heuristic indicator",f"{conf}% (not calibrated)"],["Spectral centroid",f"{centroid:.0f} Hz"],["Zero-crossing rate",f"{zcr:.3f}"],["Spectral flatness",f"{flatness:.3f}"],["Harmonic/percussive ratio",f"{ratio:.2f}"]],columns=["Measurement","Value"])
    except gr.Error: raise
    except Exception as exc: raise gr.Error(f"Voice/music analysis failed: {str(exc)[:180]}.")

