def predict_audio(path, history):
    r = analyse_file(path)
    history = list(history or [])
    history.insert(0, {
        "Time": datetime.datetime.now().strftime("%H:%M:%S"),
        "Song/Track": r["song_title"],
        "Genre": r["top"].title(),
        "Predicted Singer": r["artist"],
        "Confidence": f'{r["conf"]*100:.1f}%',
        "Tempo": f'{r["tempo"]:.0f} BPM',
        "Key": r["key"]
    })
    return (result_html(r), r["fig"], pd.DataFrame(history), report_file(r, r["song_title"]), history)

def vibe_report(path, verified=True):
    # Estimate mood and listening vibe from uploaded audio.
    if not verified:
        raise gr.Error("Please tick the ‘I’m not a robot’ box before using this feature.")
    if not path or not isinstance(path, (str, os.PathLike)) or not os.path.isfile(path):
        raise gr.Error("Please upload an audio file first.")
    try:
        y, sr = load_audio_compatible(path, sr=22050, mono=True, duration=90)
        if len(y) < sr:
            raise gr.Error("Please upload at least one second of audio.")
        tempo_raw = librosa.beat.beat_track(y=y, sr=sr)[0]
        bpm = float(np.atleast_1d(tempo_raw)[0])
        rms = float(np.mean(librosa.feature.rms(y=y)))
        centroid = float(np.mean(librosa.feature.spectral_centroid(y=y, sr=sr)))
        rolloff = float(np.mean(librosa.feature.spectral_rolloff(y=y, sr=sr)))
        zcr = float(np.mean(librosa.feature.zero_crossing_rate(y)))
        harmonic, percussive = librosa.effects.hpss(y)
        harmonic_ratio = float(np.mean(np.abs(harmonic)) / (np.mean(np.abs(y)) + 1e-9))
        loud_db = float(20 * np.log10(rms + 1e-9))
    except gr.Error:
        raise
    except Exception as exc:
        raise gr.Error(f"Could not analyze this audio: {str(exc)[:180]}. Try an MP3 or WAV file.")

    # Normalize rough acoustic measurements into easy-to-read 0–100 indicators.
    energy = int(np.clip((loud_db + 45) / 35 * 100, 0, 100))
    brightness = int(np.clip(centroid / 5000 * 100, 0, 100))
    dance = int(np.clip((min(bpm, 180) / 180 * 55) + (min(zcr, .2) / .2 * 20) + (energy * .25), 0, 100))
    if energy >= 68 and bpm >= 115:
        mood, emoji, advice = "High-energy / Party", "⚡", "Try it for workouts, parties, or a high-energy playlist."
    elif energy <= 35 and bpm < 95:
        mood, emoji, advice = "Calm / Relaxed", "🌙", "It may fit a relaxing, late-night, or focus playlist."
    elif brightness >= 60 and bpm >= 100:
        mood, emoji, advice = "Bright / Uplifting", "☀️", "It may suit a feel-good, driving, or morning playlist."
    elif bpm < 90:
        mood, emoji, advice = "Chill / Slow Groove", "🌊", "Try it for a mellow, slow-groove, or wind-down playlist."
    else:
        mood, emoji, advice = "Balanced / Groovy", "🎧", "It may work well in a mixed everyday listening playlist."

    title = os.path.basename(str(path))
    html = f'''<div class="result" style="padding:24px;border-radius:20px;background:linear-gradient(135deg,#211747,#3b1850);color:#fff;">
      <div style="font-size:42px">{emoji}</div><h2 style="margin:8px 0">{mood}</h2>
      <p style="opacity:.86">Vibe report for <b>{title}</b></p>
      <div style="display:flex;flex-wrap:wrap;gap:10px;margin:18px 0">
        <span class="chip">🥁 {bpm:.0f} BPM</span><span class="chip">🔋 Energy {energy}/100</span>
        <span class="chip">✨ Brightness {brightness}/100</span><span class="chip">🕺 Dance feel {dance}/100</span>
      </div><p>{advice}</p><small style="opacity:.72">Mood and dance feel are estimates based on audio features, not definitive judgments.</small></div>'''
    metrics = [energy, brightness, dance, int(np.clip(bpm / 180 * 100, 0, 100))]
    labels = ["Energy", "Brightness", "Dance feel", "Tempo index"]
    fig, ax = plt.subplots(figsize=(8, 3.5), facecolor="#14102e")
    ax.set_facecolor("#1d1940")
    bars = ax.bar(labels, metrics, color=["#9d86ff", "#ec4899", "#34d399", "#fbbf24"])
    ax.set_ylim(0, 100)
    ax.set_ylabel("Relative score (0–100)", color="#cfc8ff")
    ax.tick_params(axis="x", colors="#cfc8ff", rotation=8)
    ax.tick_params(axis="y", colors="#cfc8ff")
    for spine in ax.spines.values(): spine.set_color("#514477")
    ax.bar_label(bars, fmt="%d", color="white", padding=3)
    fig.tight_layout()
    rows = [
        ["Estimated mood", mood, "Rule-based summary of acoustic features"],
        ["Tempo", f"{bpm:.1f} BPM", "Estimated beats per minute"],
        ["Energy", f"{energy}/100", f"Average loudness: {loud_db:.1f} dBFS"],
        ["Brightness", f"{brightness}/100", f"Spectral centroid: {centroid:.0f} Hz"],
        ["Dance feel", f"{dance}/100", "Heuristic score from tempo, energy, and zero-crossing rate"],
        ["Spectral rolloff", f"{rolloff:.0f} Hz", "Frequency below which most spectral energy lies"],
        ["Harmonic character", f"{harmonic_ratio:.2f}", "Rough harmonic-to-total amplitude indicator"],
    ]
    return html, fig, pd.DataFrame(rows, columns=["Metric", "Estimated value", "What it means"])


def verified_vibe_report(path, verified):
    return vibe_report(path, verified)


def compare(a, b):
    if a is None or b is None:
        raise gr.Error("Please upload both audio files.")
    ra, rb = analyse_file(a), analyse_file(b)
    # The two tracks can have different top-k genre labels; compare on their union.
    labels = sorted(set(ra["probs"]) | set(rb["probs"]))
    va = np.array([ra["probs"].get(label, 0.0) for label in labels], dtype=float)
    vb = np.array([rb["probs"].get(label, 0.0) for label in labels], dtype=float)
    denom = float(np.linalg.norm(va) * np.linalg.norm(vb))
    sim = float(va @ vb / denom) if denom else 0.0

    fig, ax = plt.subplots(figsize=(9, 3.6), facecolor="#14102e")
    ax.set_facecolor("#1d1940")
    x = np.arange(len(labels))
    ax.bar(x - .2, va, .4, color="#9d86ff", label="Song A")
    ax.bar(x + .2, vb, .4, color="#ec4899", label="Song B")
    ax.set_xticks(x)
    ax.set_xticklabels([l.title() for l in labels], rotation=30, color="#cfc8ff", fontsize=8)
    ax.tick_params(colors="#cfc8ff")
    ax.legend(frameon=False, labelcolor="#e9e5ff")
    for s in ax.spines.values():
        s.set_color("#322d63")
    fig.tight_layout()
    plt.close(fig)

    html = f"""
    <div class="result" style="--c:#9d86ff">
      <div class="top">
        <div class="ring" style="--p:{sim*100:.0f}"><span>{sim*100:.0f}%</span></div>
        <div>
          <h2>{'Very Similar' if sim>.8 else 'Somewhat Similar' if sim>.5 else 'Different'}</h2>
          <p>Song A: {style(ra['top'])[1]} {ra['top'].title()} | Singer Style: {ra['artist']}<br>
          Song B: {style(rb['top'])[1]} {rb['top'].title()} | Singer Style: {rb['artist']}</p>
        </div>
      </div>
    </div>
    """
    return html, fig

# ============================ 8) PRO INTERACTIVE MUSIC FEATURES ============================
def _safe_audio_stats(path, duration=90):
    """Return consistent low-cost acoustic stats for interactive tools."""
    if not path or not os.path.isfile(path):
        raise gr.Error("Upload a valid audio file first.")
    y, sr = load_audio_compatible(path, sr=22050, mono=True, duration=duration)
    if len(y) < sr:
        raise gr.Error("Please upload an audio clip at least one second long.")
    tempo = float(np.atleast_1d(librosa.beat.beat_track(y=y, sr=sr)[0])[0])
    rms = float(np.mean(librosa.feature.rms(y=y)))
    centroid = float(np.mean(librosa.feature.spectral_centroid(y=y, sr=sr)))
    zcr = float(np.mean(librosa.feature.zero_crossing_rate(y)))
    chroma = np.mean(librosa.feature.chroma_stft(y=y, sr=sr), axis=1)
    duration_s = len(y) / sr
    return {"y": y, "sr": sr, "tempo": tempo, "rms": rms, "centroid": centroid,
            "zcr": zcr, "chroma": chroma, "duration": duration_s,
            "energy": "High" if rms > .12 else ("Medium" if rms > .055 else "Low"),
            "danceability_est": int(np.clip(100 - abs(tempo - 120) * .55 - zcr * 80, 0, 100))}


def song_dna_scan(path, verified):
    require_human(verified)
    if not path: raise gr.Error("Upload a song to scan its DNA.")
    r = analyse_file(path)
    s = _safe_audio_stats(path)
    # Stable visual fingerprint derived from the track's audio measurements.
    digest = hashlib.sha256(np.asarray(s["chroma"], dtype=np.float32).tobytes() + os.path.basename(path).encode()).hexdigest()[:12].upper()
    fig, ax = plt.subplots(figsize=(8, 3.8), facecolor="#14102e")
    ax.set_facecolor("#1d1940")
    labels = ["Tempo", "Energy", "Brightness", "Dance feel", "ZCR"]
    vals = [np.clip(s["tempo"] / 180 * 100, 0, 100), np.clip(s["rms"] * 500, 0, 100),
            np.clip(s["centroid"] / 5000 * 100, 0, 100), s["danceability_est"], np.clip(s["zcr"] * 500, 0, 100)]
    bars = ax.bar(labels, vals, color=["#b794ff", "#f472b6", "#67e8f9", "#a7f3d0", "#fcd34d"])
    ax.set_ylim(0, 100); ax.set_ylabel("Normalized index (0–100)", color="#ddd6fe")
    ax.tick_params(colors="#ddd6fe", axis="x", rotation=12); ax.tick_params(colors="#ddd6fe", axis="y")
    for sp in ax.spines.values(): sp.set_color("#514477")
    ax.bar_label(bars, fmt="%.0f", color="white", padding=3); fig.tight_layout()
    html = (f'<div class="result"><h2>🧬 Song DNA Scan</h2><p><b>{os.path.basename(path)}</b></p>'
            f'<div class="chips"><span class="chip"><small>DNA fingerprint</small>{digest}</span>'
            f'<span class="chip"><small>Predicted genre</small>{r["top"].title()}</span>'
            f'<span class="chip"><small>Tempo</small>{s["tempo"]:.0f} BPM</span>'
            f'<span class="chip"><small>Duration analyzed</small>{s["duration"]:.1f} sec</span>'
            f'<span class="chip"><small>Energy</small>{s["energy"]}</span>'
            f'<span class="chip"><small>Dance feel estimate</small>{s["danceability_est"]}/100</span></div>'
            '<p>Fingerprint and dance-feel values are derived from acoustic features; they are not official catalog metadata.</p></div>')
    table = pd.DataFrame([["Predicted genre", r["top"].title()], ["Model confidence", f'{r["conf"]*100:.1f}%'],
                          ["Tempo", f'{s["tempo"]:.1f} BPM'], ["Energy estimate", s["energy"]],
                          ["Spectral brightness", f'{s["centroid"]:.0f} Hz'], ["Dance-feel estimate", f'{s["danceability_est"]}/100'],
                          ["Fingerprint ID", digest]], columns=["Measurement", "Result"])
    return html, fig, table


