def mood_studio(path, selected_mood, verified):
    require_human(verified)
    if not path: raise gr.Error("Upload a track before comparing its mood.")
    s = _safe_audio_stats(path)
    # Simple transparent baseline: it compares acoustic indicators, not a trained emotion model.
    tempo = s["tempo"]; rms = s["rms"]
    if selected_mood == "Chill": fit = 100 - min(100, abs(tempo-80)*.8 + rms*120)
    elif selected_mood == "Sad": fit = 100 - min(100, abs(tempo-75)*.7 + rms*100)
    elif selected_mood == "Energetic": fit = min(100, tempo*.45 + rms*250)
    elif selected_mood == "Romantic": fit = 100 - min(100, abs(tempo-90)*.6 + abs(s["centroid"]-2200)/60)
    else: fit = min(100, tempo*.42 + rms*220)
    fig, ax = plt.subplots(figsize=(7, 3), facecolor="#14102e"); ax.set_facecolor("#1d1940")
    ax.barh(["Selected mood fit", "Energy index", "Dance-feel estimate"], [fit, np.clip(rms*500,0,100), s["danceability_est"]], color=["#c084fc", "#f472b6", "#67e8f9"])
    ax.set_xlim(0,100); ax.tick_params(colors="#ddd6fe"); ax.set_xlabel("Heuristic index (0–100)", color="#ddd6fe")
    for sp in ax.spines.values(): sp.set_color("#514477")
    fig.tight_layout()
    html = f'<div class="result"><h2>🎭 Mood Studio: {selected_mood}</h2><p>Acoustic mood-fit estimate: <b>{fit:.0f}/100</b></p><div class="chips"><span class="chip"><small>Tempo</small>{tempo:.0f} BPM</span><span class="chip"><small>Energy</small>{s["energy"]}</span><span class="chip"><small>Brightness</small>{s["centroid"]:.0f} Hz</span></div><p>This is a transparent heuristic, not a trained emotion detector or a statement about the listener’s feelings.</p></div>'
    return html, fig


def dj_set_planner(files, verified):
    require_human(verified)
    if not files or len(files) < 2: raise gr.Error("Upload at least two songs to plan a DJ set.")
    rows=[]
    for p in files:
        if not p or not os.path.isfile(p): continue
        s=_safe_audio_stats(p)
        rows.append({"Track":os.path.basename(p),"BPM":round(s["tempo"],1),"Energy":s["energy"],"Energy index":round(float(s["rms"]*500),1),"Duration (sec)":round(s["duration"],1),"Path":p})
    if len(rows)<2: raise gr.Error("Could not analyze at least two usable audio files.")
    # Sort low-to-high estimated energy, then by tempo for a gradual warm-up sequence.
    rows.sort(key=lambda x:(x["Energy index"],x["BPM"]))
    for i,row in enumerate(rows,1): row["Set order"]=i
    df=pd.DataFrame(rows)[["Set order","Track","BPM","Energy","Energy index","Duration (sec)"]]
    return '<div class="result"><h2>🎛️ AI DJ Set Plan</h2><p>Tracks are arranged from lower to higher measured RMS energy, with tempo as a secondary sort. This is a suggested order, not a beat-matched mix.</p></div>', df


def transition_checker(a, b, verified):
    require_human(verified)
    if not a or not b: raise gr.Error("Upload both Song A and Song B.")
    sa=_safe_audio_stats(a); sb=_safe_audio_stats(b)
    bpm_gap=abs(sa["tempo"]-sb["tempo"])
    ratio_gap=abs(sa["tempo"]-sb["tempo"]/2) if sb["tempo"] else 999
    best_gap=min(bpm_gap, ratio_gap)
    chroma_sim=float(np.dot(sa["chroma"],sb["chroma"])/(np.linalg.norm(sa["chroma"])*np.linalg.norm(sb["chroma"])+1e-9))
    score=float(np.clip(100-best_gap*2.0-abs(sa["rms"]-sb["rms"])*180+max(0,chroma_sim)*8,0,100))
    label="Potentially compatible" if score>=70 else ("Try a slower transition" if score>=45 else "Large contrast")
    return f'<div class="result"><h2>🔀 Transition Compatibility</h2><div class="chips"><span class="chip"><small>Estimated compatibility</small>{score:.0f}/100</span><span class="chip"><small>Song A BPM</small>{sa["tempo"]:.0f}</span><span class="chip"><small>Song B BPM</small>{sb["tempo"]:.0f}</span><span class="chip"><small>Assessment</small>{label}</span></div><p>Heuristic based on tempo gap, energy difference, and chroma similarity. It does not analyze beat-grid alignment, key compatibility, or actual DJ mix quality.</p></div>', pd.DataFrame([["Tempo difference",f"{bpm_gap:.1f} BPM"],["Half/double-time alternative",f"{ratio_gap:.1f} BPM"],["Chroma similarity",f"{chroma_sim:.3f}"],["Energy A/B",f"{sa['rms']:.3f} / {sb['rms']:.3f}"]],columns=["Measurement","Result"])


def genre_evolution(path, verified):
    require_human(verified)
    if not path: raise gr.Error("Upload a song first.")
    if clf is None: raise gr.Error("The pretrained genre model did not load in this runtime.")
    y,sr=load_audio_compatible(path,sr=16000,mono=True,duration=120)
    chunk=int(sr*5); rows=[]
    for start in range(0,len(y),chunk):
        seg=y[start:start+chunk]
        if len(seg)<sr*2: continue
        try:
            preds=clf({"raw":seg.astype(np.float32),"sampling_rate":sr},top_k=3)
            top=preds[0] if isinstance(preds,list) else preds
            rows.append({"Time (sec)":start/sr,"Top genre":str(top["label"]),"Score":float(top["score"])})
        except Exception: continue
    if not rows: raise gr.Error("No usable audio segments could be classified.")
    df=pd.DataFrame(rows)
    fig,ax=plt.subplots(figsize=(9,3.5),facecolor="#14102e"); ax.set_facecolor("#1d1940")
    ax.plot(df["Time (sec)"],df["Score"]*100,marker="o",color="#c084fc")
    ax.set_ylim(0,100); ax.set_xlabel("Time (seconds)",color="#ddd6fe"); ax.set_ylabel("Top-label score (%)",color="#ddd6fe"); ax.tick_params(colors="#ddd6fe")
    for sp in ax.spines.values(): sp.set_color("#514477")
    fig.tight_layout()
    return '<div class="result"><h2>📈 Genre Evolution Timeline</h2><p>Each point is the top model label for a five-second segment. Changes can reflect musical sections or model variability.</p></div>',fig,df


def smart_playlist(files, genre_filter, min_bpm, max_bpm, mood_filter, verified):
    require_human(verified)
    if not files: raise gr.Error("Upload a local music library first.")
    if min_bpm > max_bpm: raise gr.Error("Minimum BPM must be less than or equal to maximum BPM.")
    rows=[]
    for p in files:
        if not p or not os.path.isfile(p): continue
        try:
            s=_safe_audio_stats(p)
            pred="Unknown"; conf=0.0
            if clf is not None:
                yy,ss=load_audio_compatible(p,sr=16000,mono=True,duration=25)
                pp=clf({"raw":yy.astype(np.float32),"sampling_rate":ss},top_k=1)
                pred=str(pp[0]["label"] if isinstance(pp,list) else pp["label"])
                conf=float(pp[0]["score"] if isinstance(pp,list) else pp["score"])
            mood="Energetic" if s["tempo"]>=110 and s["rms"]>.08 else ("Chill" if s["tempo"]<95 else "Balanced")
            rows.append({"Track":os.path.basename(p),"Genre":pred,"Confidence %":round(conf*100,1),"BPM":round(s["tempo"],1),"Mood estimate":mood,"Energy":s["energy"]})
        except Exception as e: print(f"Playlist skipped {p}: {e}")
    df=pd.DataFrame(rows)
    if df.empty: raise gr.Error("No uploaded tracks could be analyzed.")
    if genre_filter!="All": df=df[df["Genre"].str.lower()==genre_filter.lower()]
    df=df[(df["BPM"]>=float(min_bpm))&(df["BPM"]<=float(max_bpm))]
    if mood_filter!="Any": df=df[df["Mood estimate"]==mood_filter]
    if df.empty: return "<div class='result'><h2>No tracks match</h2><p>Try widening the genre, BPM, or mood filters.</p></div>",df
    return f'<div class="result"><h2>🎶 Smart Playlist</h2><p>Found <b>{len(df)}</b> track(s) matching your filters. Genre and mood are estimates.</p></div>',df


def studio_assistant(path, question, verified):
    require_human(verified)
    if not path: raise gr.Error("Upload a song first.")
    r=analyse_file(path); s=_safe_audio_stats(path)
    q=(question or "Explain this song").lower()
    if "tempo" in q or "bpm" in q: answer=f"The estimated tempo is {s['tempo']:.0f} BPM. This value is inferred from beat patterns and can be off by half-time or double-time."
    elif "bright" in q or "frequency" in q: answer=f"Average spectral centroid is {s['centroid']:.0f} Hz. A higher centroid often corresponds to a brighter-sounding spectrum, but it is not a direct measure of quality."
    elif "confidence" in q: answer=f"The top genre is {r['top'].title()} with a model score of {r['conf']*100:.1f}%. A model score is not a guarantee of correctness."
    elif "mood" in q or "energy" in q: answer=f"The simple acoustic profile estimates {s['energy'].lower()} energy at {s['tempo']:.0f} BPM. Mood labels are heuristic and may not match how a listener feels."
    else: answer=f"The model predicts {r['top'].title()} ({r['conf']*100:.1f}% score). The track is about {s['duration']:.1f} seconds in the analyzed excerpt, at approximately {s['tempo']:.0f} BPM, with {s['energy'].lower()} RMS energy. Try asking about tempo, mood, brightness, or confidence for a focused explanation."
    return f"### 🎚️ Studio Assistant\n\n{answer}\n\n**Model:** `{MODEL_NAME or 'Unavailable'}`\n\n*This assistant uses measured audio features and fixed explanations; it is not a general-purpose language model.*"


def dataset_explorer(csv_path, target_col, selected_genre):
    if not csv_path: raise gr.Error("Upload a labelled CSV file.")
    try: df=pd.read_csv(csv_path)
    except Exception as e: raise gr.Error(f"Could not read CSV: {e}")
    if df.empty: raise gr.Error("The CSV is empty.")
    summary=pd.DataFrame([["Rows",len(df)],["Columns",len(df.columns)],["Missing cells",int(df.isna().sum().sum())],["Duplicate rows",int(df.duplicated().sum())],["Numeric columns",int(df.select_dtypes(include=np.number).shape[1])]],columns=["Dataset check","Value"])
    fig=None
    if target_col in df.columns:
        counts=df[target_col].fillna("<missing>").astype(str).value_counts()
        if selected_genre!="All": counts=counts[counts.index==selected_genre]
        fig,ax=plt.subplots(figsize=(8,3.5),facecolor="#14102e"); ax.set_facecolor("#1d1940")
        if len(counts): ax.bar(counts.index.astype(str),counts.values,color="#a78bfa"); ax.tick_params(axis="x",rotation=25,colors="#ddd6fe"); ax.tick_params(axis="y",colors="#ddd6fe")
        ax.set_ylabel("Rows",color="#ddd6fe")
        for sp in ax.spines.values(): sp.set_color("#514477")
        fig.tight_layout()
        summary=pd.concat([summary,pd.DataFrame([["Target column",target_col],["Unique target labels",df[target_col].nunique(dropna=True)]],columns=summary.columns)],ignore_index=True)
    else:
        summary=pd.concat([summary,pd.DataFrame([["Target column warning",f"'{target_col}' not found"]],columns=summary.columns)],ignore_index=True)
    preview=df.head(100)
    return summary,fig,preview


def compare_models(csv_path, target_col, verified):
    require_human(verified)
    if not csv_path: raise gr.Error("Upload a labelled feature CSV.")
    df=pd.read_csv(csv_path)
    if target_col not in df.columns: raise gr.Error(f"Target column '{target_col}' was not found.")
    y=df[target_col].astype(str); X=df.drop(columns=[target_col]).select_dtypes(include=np.number)
    good=y.notna(); X=X.loc[good].replace([np.inf,-np.inf],np.nan); y=y.loc[good]
    X=X.fillna(X.median(numeric_only=True)).fillna(0)
    if X.shape[1]==0: raise gr.Error("No numeric feature columns were found.")
    counts=y.value_counts(); keep=counts[counts>=2].index; X=X[y.isin(keep)]; y=y[y.isin(keep)]
    if len(y)<8 or y.nunique()<2: raise gr.Error("Need at least 8 usable rows and two classes with at least two examples each.")
    try: Xtr,Xte,ytr,yte=train_test_split(X,y,test_size=.2,random_state=42,stratify=y)
    except ValueError: Xtr,Xte,ytr,yte=train_test_split(X,y,test_size=.2,random_state=42)
    models={"SVM":Pipeline([("scale",StandardScaler()),("classifier",SVC(probability=True,class_weight="balanced",random_state=42))]),"Random Forest":RandomForestClassifier(n_estimators=180,class_weight="balanced",random_state=42,n_jobs=-1),"Extra Trees":ExtraTreesClassifier(n_estimators=180,class_weight="balanced",random_state=42,n_jobs=-1)}
    rows=[]
    for name,m in models.items():
        try:
            m.fit(Xtr,ytr); pred=m.predict(Xte)
            rows.append({"Model":name,"Accuracy %":round(accuracy_score(yte,pred)*100,2),"Macro F1":round(__import__('sklearn.metrics').metrics.f1_score(yte,pred,average="macro",zero_division=0),3),"Weighted F1":round(__import__('sklearn.metrics').metrics.f1_score(yte,pred,average="weighted",zero_division=0),3)})
        except Exception as e: rows.append({"Model":name,"Accuracy %":np.nan,"Macro F1":np.nan,"Weighted F1":np.nan,"Error":str(e)[:100]})
    result=pd.DataFrame(rows)
    fig,ax=plt.subplots(figsize=(7,3.5),facecolor="#14102e"); ax.set_facecolor("#1d1940")
    valid=result.dropna(subset=["Accuracy %"])
    if len(valid):
        bars=ax.bar(valid["Model"],valid["Accuracy %"],color=["#c084fc","#f472b6","#67e8f9"][:len(valid)]); ax.set_ylim(0,100); ax.bar_label(bars,fmt="%.1f%%",color="white")
    ax.set_ylabel("Held-out accuracy (%)",color="#ddd6fe"); ax.tick_params(colors="#ddd6fe")
    for sp in ax.spines.values(): sp.set_color("#514477")
    fig.tight_layout()
    best=result.dropna(subset=["Accuracy %"]).sort_values("Accuracy %",ascending=False).head(1)
    msg=f'<div class="result"><h2>🧪 Model Comparison Lab</h2><p>Compared models on the same random 80/20 split. Best observed accuracy: <b>{best.iloc[0]["Model"]} — {best.iloc[0]["Accuracy %"]:.2f}%</b>.</p><p>Small datasets and track leakage can make these scores unreliable; use group-aware splits by song/artist for serious evaluation.</p></div>' if len(best) else "No model completed successfully."
    return msg,fig,result


