def artist_explorer(name):
    """Use public catalog search when reachable; gracefully fall back to links."""
    import urllib.parse
    import requests
    a=ARTIST_EXPLORER[name]
    q=urllib.parse.quote_plus(a["search"])
    spotify=f"https://open.spotify.com/search/{q}"
    apple=f"https://music.apple.com/search?term={q}"
    image_url=""
    songs=[]
    # Wikipedia summary is used only for a portrait thumbnail; Apple Search API supplies track metadata.
    try:
        wiki_title=urllib.parse.quote(name.replace(" ","_"), safe="_()")
        wr=requests.get(f"https://en.wikipedia.org/api/rest_v1/page/summary/{wiki_title}",timeout=4,headers={"User-Agent":"GenreLensPro/1.0 (student music analysis project)"})
        if wr.ok: image_url=(wr.json().get("thumbnail") or {}).get("source","")
    except Exception: pass
    try:
        resp=requests.get("https://itunes.apple.com/search",params={"term":a["search"],"entity":"song","limit":8},timeout=5)
        if resp.ok:
            for item in resp.json().get("results",[]):
                if item.get("trackName") and item.get("trackViewUrl"):
                    songs.append({"title":item.get("trackName",""),"artist":item.get("artistName",name),"duration":item.get("trackTimeMillis"),"art":item.get("artworkUrl100",""),"url":item.get("trackViewUrl","")})
    except Exception: pass
    portrait=(f'<img src="{image_url}" alt="{name}" style="width:96px;height:96px;object-fit:cover;border-radius:50%;border:2px solid #b794ff">' if image_url else '<div style="width:96px;height:96px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#7c3aed,#db2777);font-size:2rem">🎤</div>')
    song_html=""
    for item in songs:
        duration=(f'{item["duration"]//60000}:{(item["duration"]//1000)%60:02d}' if item["duration"] else "Length unavailable")
        cover=(f'<img src="{item["art"]}" alt="cover" style="width:54px;height:54px;border-radius:9px;object-fit:cover">' if item["art"] else '')
        song_html += f'<div style="display:flex;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.12)">{cover}<div style="flex:1"><b>{item["title"]}</b><br><small>{item["artist"]} · {duration}</small></div><a href="{item["url"]}" target="_blank" rel="noopener">Listen ↗</a></div>'
    if not song_html: song_html='<p>Live track metadata was not reachable in this runtime. Use the catalog search links below to explore available songs.</p>'
    return (f'<div class="result"><div style="display:flex;gap:16px;align-items:center">{portrait}<div><h2>🎤 {name}</h2><p>{a["style"]}</p></div></div>'
            f'<p>{a["bio"]}</p><p><a href="{spotify}" target="_blank" rel="noopener">Search on Spotify ↗</a> &nbsp; | &nbsp; <a href="{apple}" target="_blank" rel="noopener">Search Apple Music ↗</a></p>'
            f'<h3>Available track results</h3>{song_html}<p><small>Track listings, artwork, durations, and links are retrieved from public catalog endpoints when available. Genre prediction cannot identify the singer of an uploaded recording.</small></p></div>')


