LIBRARY_PATH = os.path.join(os.getcwd(), "genrelens_music_library.json")
def load_music_library():
    try:
        with open(LIBRARY_PATH, "r", encoding="utf-8") as f: data=json.load(f)
        return data if isinstance(data,list) else []
    except Exception: return []

def add_library_entry(title, artist, genre, notes):
    if not (title or "").strip(): raise gr.Error("Enter a track title first.")
    items=load_music_library()
    entry={"Title":title.strip(),"Artist":(artist or "").strip(),"Genre":genre,"Notes":(notes or "").strip(),"Added":datetime.datetime.now().isoformat(timespec="seconds")}
    if not any(x.get("Title","" ).lower()==entry["Title"].lower() and x.get("Artist","").lower()==entry["Artist"].lower() for x in items): items.insert(0,entry)
    with open(LIBRARY_PATH,"w",encoding="utf-8") as f: json.dump(items,f,ensure_ascii=False,indent=2)
    return f'<div class="result"><h2>📚 Saved to Music Library</h2><p><b>{entry["Title"]}</b> is in your local library.</p><p>For durable storage across runtime resets, export the library and keep the JSON file.</p></div>', pd.DataFrame(items)

def show_music_library():
    items=load_music_library()
    return (f'<div class="result"><h2>📚 Music Library</h2><p>{len(items)} saved item(s).</p></div>',pd.DataFrame(items) if items else pd.DataFrame(columns=["Title","Artist","Genre","Notes","Added"]))

def export_music_library():
    items=load_music_library()
    if not items: raise gr.Error("Your library is empty. Save a track entry first.")
    path=os.path.join(tempfile.gettempdir(),f"genrelens_library_{int(time.time())}.json")
    with open(path,"w",encoding="utf-8") as f: json.dump(items,f,ensure_ascii=False,indent=2)
    return path

def import_music_library(path):
    if not path: raise gr.Error("Choose a previously exported GenreLens library JSON file.")
    try:
        incoming=json.load(open(path,"r",encoding="utf-8"))
        if not isinstance(incoming,list): raise ValueError("Expected a list of library entries")
        merged=load_music_library(); seen={(str(x.get("Title","")).lower(),str(x.get("Artist","")).lower()) for x in merged}
        for item in incoming:
            if isinstance(item,dict) and (str(item.get("Title","")).lower(),str(item.get("Artist","")).lower()) not in seen:
                merged.append(item); seen.add((str(item.get("Title","")).lower(),str(item.get("Artist","")).lower()))
        with open(LIBRARY_PATH,"w",encoding="utf-8") as f: json.dump(merged,f,ensure_ascii=False,indent=2)
        return f'<div class="result"><h2>Import complete</h2><p>Library now contains {len(merged)} item(s).</p></div>',pd.DataFrame(merged)
    except Exception as e: raise gr.Error(f"Could not import library: {str(e)[:160]}")

