# ============================ HUMAN VERIFICATION ============================
def require_human(verified):
    """Lightweight user confirmation; this is not a full CAPTCHA/security system."""
    if not verified:
        raise gr.Error("Please tick the ‘I’m not a robot’ box before using this feature.")


def verified_predict_audio(path, history, verified):
    require_human(verified)
    try:
        return predict_audio(path, history)
    except gr.Error:
        raise
    except Exception as exc:
        print(f"Unexpected audio prediction error: {exc}")
        raise gr.Error(f"Audio analysis could not finish ({exc.__class__.__name__}). Try another MP3/WAV file. Check the Colab output for details.")


def verified_compare(a, b, verified):
    require_human(verified)
    try:
        return compare(a, b)
    except gr.Error:
        raise
    except Exception as exc:
        print(f"Unexpected comparison error: {exc}")
        raise gr.Error(f"Track comparison could not finish ({exc.__class__.__name__}). Try two valid MP3/WAV files.")


