def _assistant_norm(text):
    return re.sub(r"[^a-z0-9]+", " ", str(text or "").lower()).strip()


def _assistant_owner_names():
    try:
        names = [str(n).replace("(Leader)", "").strip() for n, _ in OWNERS]
        return [n for n in names if n]
    except Exception:
        return []


def _assistant_last_prediction(hist):
    rows = list(hist or [])
    if not rows:
        return ("You haven't analysed any song in this session yet. 🎧 Open **Predict Audio File / Mic**, "
                "upload a song (or record a clip) and press **Predict Genre & Singer**. "
                "Then ask me again and I'll summarise the result for you.")
    last = rows[0]
    parts = [
        f"**Latest result** (session history keeps {len(rows)} analysis{'es' if len(rows) != 1 else ''}):",
        f"- 🎵 Track: **{last.get('Song/Track', '—')}**",
        f"- 🎸 Genre: **{last.get('Genre', '—')}** (model score {last.get('Confidence', '—')})",
        f"- 🥁 Tempo: {last.get('Tempo', '—')}   ·   🎹 Key: {last.get('Key', '—')}",
        f"- 🎤 Style match: {last.get('Predicted Singer', '—')}",
        "\nRemember: the score is the model's own confidence, not a guarantee. "
        "Open **Prediction Confidence Center** for the top-5 breakdown.",
    ]
    return "\n".join(parts)


