_ASSISTANT_GREETING_WORDS = {"hi", "hii", "hiii", "hello", "hey", "heyy", "hlo", "yo", "namaste", "sup", "hola"}
_ASSISTANT_GREETING_PHRASES = ("good morning", "good afternoon", "good evening", "how are you", "whats up", "what s up")


def _assistant_score(text, keys):
    padded = " " + text + " "
    score = 0.0
    for phrase, weight in keys:
        if len(phrase) <= 4:
            hit = (" " + phrase + " ") in padded
        else:
            hit = (" " + phrase) in padded
        if hit:
            score += weight
    return score


def seven_eleven_reply(message, hist=None):
    """Return the assistant's answer (markdown text) for one user message."""
    raw = str(message or "").strip()
    text = _assistant_norm(raw)
    if not text:
        return "Type a question and I'll help! For example: *What is BPM?*"
    if len(raw) > 600:
        raw = raw[:600]
        text = _assistant_norm(raw)

    words = set(text.split())
    # Greetings: only when the message is short, so "hey, how do I predict?" still gets a real answer.
    if len(words) <= 4 and (words & _ASSISTANT_GREETING_WORDS or any(p in text for p in _ASSISTANT_GREETING_PHRASES)):
        return ("Hello! 👋 I'm **7-11 A.I**. I can explain any tool on this site, help you read your results, "
                "or fix problems. What would you like to do?")

    best_id, best_score, best_answer = None, 0.0, None
    for intent_id, keys, answer in ASSISTANT_INTENTS:
        score = _assistant_score(text, keys)
        if score > best_score:
            best_id, best_score, best_answer = intent_id, score, answer

    if best_answer is not None and best_score >= 2.0:
        return best_answer(hist) if callable(best_answer) else best_answer
    if best_answer is not None and best_score >= 1.0 and len(words) <= 3:
        # Short one/two-word questions like "bpm", "genres", "mic" deserve a direct answer too.
        return best_answer(hist) if callable(best_answer) else best_answer

    # Fallback: try a fuzzy match against intent names / quick questions, then offer suggestions.
    candidates = {q: q for q in ASSISTANT_QUICK_QUESTIONS}
    close = difflib.get_close_matches(raw, list(candidates), n=1, cutoff=0.6)
    hint = f"\n\nDid you mean: **{close[0]}**?" if close else ""
    if best_answer is not None and best_score >= 1.0:
        body = best_answer(hist) if callable(best_answer) else best_answer
        return ("I'm not 100% sure what you meant, but this might help:\n\n" + body + hint)
    return ("🤔 I'm not sure I understood that. I know about this website's tools, music terms (BPM, key, mood, spectrogram…), "
            "model accuracy, troubleshooting and getting a permanent link."
            + hint +
            "\n\nTry: *What can you do?*, *How do I predict a genre?*, *What is BPM?*, or *Show my last prediction.*")


def seven_eleven_chat(message, chat_history, hist):
    """Gradio handler: append the user message and the assistant reply to the chat history."""
    chat_history = list(chat_history or [])
    msg = str(message or "").strip()
    if not msg:
        return chat_history, ""
    try:
        reply = seven_eleven_reply(msg, hist)
    except Exception as exc:  # never let the helper crash the page
        print(f"7-11 A.I error: {exc}")
        reply = "Sorry, I hit a small problem answering that. Please try rephrasing your question."
    chat_history.append({"role": "user", "content": msg})
    chat_history.append({"role": "assistant", "content": reply})
    return chat_history, ""


def seven_eleven_clear():
    return [{"role": "assistant", "content": ASSISTANT_GREETING}], ""


def _assistant_quick_setter(text):
    def _set():
        return text
    return _set


