# Colab: Gradio makes a temporary public link (valid 72 hours). Hugging Face Spaces: the permanent link is the Space URL.
app.queue(default_concurrency_limit=2, max_size=12).launch(share=(IN_COLAB and not IN_SPACES), debug=False, show_error=True)